{"candidate":{"content":"import { useState, useEffect, useCallback, useRef } from 'react';
import { Card, groups, filters } from './directory';

interface GeographyData {
  countries: { id: string; name: string; code: string }[];
  provinces: { id: string; name: string; country_id: string }[];
  zones: { id: string; name: string; country_id: string; province_id: string }[];
}

interface ProfileResponse {
  items: Card[];
  next_cursor: string | null;
}

interface ApiError {
  error: { code: string; message: string };
}

export default function App() {
  const [geography, setGeography] = useState<GeographyData | null>(null);
  const [profiles, setProfiles] = useState<Card[]>([]);
  const [nextCursor, setNextCursor] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [countryId, setCountryId] = useState('');
  const [provinceId, setProvinceId] = useState('');
  const [zoneId, setZoneId] = useState('');

  const abortControllerRef = useRef<AbortController | null>(null);

  const fetchGeography = useCallback(async () => {
    try {
      const res = await fetch('/api/catalog/geography');
      if (!res.ok) throw new Error('Failed to fetch geography');
      const data: GeographyData = await res.json();
      setGeography(data);
    } catch (e) {
      setError('Error loading geography data');
    }
  }, []);

  const fetchProfiles = useCallback(async (cursor: string | null = null) => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    const controller = new AbortController();
    abortControllerRef.current = controller;

    const params = filters(countryId, provinceId, zoneId);
    if (cursor) {
      params.append('cursor', cursor);
    }

    try {
      const res = await fetch(`/api/profiles?${params.toString()}`, {
        signal: controller.signal
      });

      if (!res.ok) {
        const errData: ApiError = await res.json();
        throw new Error(errData.error.message || 'Failed to fetch profiles');
      }

      const data: ProfileResponse = await res.json();

      if (cursor) {
        setProfiles(prev => [...prev, ...data.items]);
      } else {
        setProfiles(data.items);
      }

      setNextCursor(data.next_cursor);
      setLoading(false);
      setError(null);
    } catch (e: any) {
      if (e.name !== 'AbortError') {
        setError(e.message || 'Failed to load profiles');
        setLoading(false);
      }
    }
  }, [countryId, provinceId, zoneId]);

  useEffect(() => {
    fetchGeography();
  }, [fetchGeography]);

  useEffect(() => {
    setLoading(true);
    setError(null);
    fetchProfiles(null);

    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, [fetchProfiles]);

  const handleCountryChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setCountryId(e.target.value);
    setProvinceId('');
    setZoneId('');
  };

  const handleProvinceChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setProvinceId(e.target.value);
    setZoneId('');
  };

  const handleZoneChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setZoneId(e.target.value);
  };

  const handleRetry = () => {
    setLoading(true);
    setError(null);
    fetchProfiles(null);
  };

  const handleLoadMore = () => {
    if (nextCursor) {
      fetchProfiles(nextCursor);
    }
  };

  const filteredProvinces = geography?.provinces.filter(p => p.country_id === countryId) || [];
  const filteredZones = geography?.zones.filter(z => z.province_id === provinceId) || [];

  const { promoted, basic } = groups(profiles);

  if (loading && profiles.length === 0) {
    return (
      <div className="app-container">
        <header>
          <h1>Directory</h1>
          <a href="/registro" className="register-link">Register</a>
        </header>
        <div className="loading-state">Loading...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="app-container">
        <header>
          <h1>Directory</h1>
          <a href="/registro" className="register-link">Register</a>
        </header>
        <div className="error-state">
          <p>{error}</p>
          <button onClick={handleRetry}>Retry</button>
        </div>
      </div>
    );
  }

  if (profiles.length === 0) {
    return (
      <div className="app-container">
        <header>
          <h1>Directory</h1>
          <a href="/registro" className="register-link">Register</a>
        </header>
        <div className="empty-state">
          <p>No profiles found.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="app-container">
      <header>
        <h1>Directory</h1>
        <a href="/registro" className="register-link">Register</a>
      </header>

      <div className="filters">
        <label>
          Country
          <select value={countryId} onChange={handleCountryChange}>
            <option value="">All</option>
            {geography?.countries.map(c => (
              <option key={c.id} value={c.id}>{c.name}</option>
            ))}
          </select>
        </label>

        <label>
          Province
          <select value={provinceId} onChange={handleProvinceChange} disabled={!countryId}>
            <option value="">All</option>
            {filteredProvinces.map(p => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
        </label>

        <label>
          Zone
          <select value={zoneId} onChange={handleZoneChange} disabled={!provinceId}>
            <option value="">All</option>
            {filteredZones.map(z => (
              <option key={z.id} value={z.id}>{z.name}</option>
            ))}
          </select>
        </label>
      </div>

      <main>
        {promoted.length > 0 && (
          <section>
            <h2>Promocionados</h2>
            <div className="card-grid">
              {promoted.map(card => (
                <div key={card.id} className="card">
                  <img src={card.main_photo} alt={card.display_name} />
                  <h3>{card.display_name}</h3>
                  <p>{card.description}</p>
                  <a href={card.whatsapp_url} target="_blank" rel="noopener noreferrer">Contact</a>
                </div>
              ))}
            </div>
          </section>
        )}

        {basic.length > 0 && (
          <section>
            <h2>Listado básico</h2>
            <div className="card-grid">
              {basic.map(card => (
                <div key={card.id} className="card">
                  <img src={card.main_photo} alt={card.display_name} />
                  <h3>{card.display_name}</h3>
                  <p>{card.description}</p>
                  <a href={card.whatsapp_url} target="_blank" rel="noopener noreferrer">Contact</a>
                </div>
              ))}
            </div>
          </section>
        )}
      </main>

      {nextCursor && (
        <div className="load-more">
          <button onClick={handleLoadMore} disabled={loading}>
            {loading ? 'Loading...' : 'Load More'}
          </button>
        </div>
      )}
    </div>
  );
}
